// 设置随机数种子，确保每次运行不同
srand(time(0));
int secret = rand() % 100 + 1;// 1-100
int guess;
while(true) {
cin >> guess;// 读取玩家输入
(guess > secret) ? cout<<"太大了!" :
(guess < secret) ? cout<<"太小了!" :
(cout<<“恭喜猜对!",break); // 输出，并退出
}

