for(int i = 1; i <= 9; i++) {// 外层循环：控制行数
     for(int j = 1; j <= i; j++) {// 内层循环：控制列数
        cout << j <<"*"<< i <<"="<< i*j <<"\t";
     }
cout << endl;// 每行结束后换行
}

